<?php require 'config.php';require 'includes/functions.php';need_login();verify();$q=$pdo->prepare("SELECT * FROM users WHERE id=?");$q->execute([user()['id']]);$me=$q->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$phone=trim($_POST['phone']);$q=$pdo->prepare("UPDATE users SET name=?,phone=? WHERE id=?");$q->execute([$name,$phone,user()['id']]);$_SESSION['user']['name']=$name;flash('Profile updated.');go('profile.php');}$title='Update profile';require 'includes/header.php';?><div class="formbox"><h1>Personal details</h1><form method="post"><?=csrf()?><label>Name<input name="name" value="<?=e($me['name'])?>" required></label><label>Email<input value="<?=e($me['email'])?>" disabled></label><label>Phone<input name="phone" value="<?=e($me['phone'])?>"></label><button class="btn">Save changes</button></form></div><?php require 'includes/footer.php';?>